INSERT INTO chapter_exclusions (source_chapter, excluded_product_text, redirects_to_chapter, redirects_to_heading, source_note_number, source_note_text) VALUES
  ('01', 'fish and crustaceans, molluscs and other aquatic invertebrates', '03', '0301', 'Note 1', 'This Chapter covers all live animals except : (a) fish and crustaceans, molluscs and other aquatic invertebrates, of heading 0301, 0306, 0307 or 0308; (b) cultures of micro-organisms and other products of heading 3002; and (c) animals of heading 9508.'),
  ('01', 'fish and crustaceans, molluscs and other aquatic invertebrates', '03', '0306', 'Note 1', 'This Chapter covers all live animals except : (a) fish and crustaceans, molluscs and other aquatic invertebrates, of heading 0301, 0306, 0307 or 0308; (b) cultures of micro-organisms and other products of heading 3002; and (c) animals of heading 9508.'),
  ('01', 'fish and crustaceans, molluscs and other aquatic invertebrates', '03', '0307', 'Note 1', 'This Chapter covers all live animals except : (a) fish and crustaceans, molluscs and other aquatic invertebrates, of heading 0301, 0306, 0307 or 0308; (b) cultures of micro-organisms and other products of heading 3002; and (c) animals of heading 9508.'),
  ('01', 'fish and crustaceans, molluscs and other aquatic invertebrates', '03', '0308', 'Note 1', 'This Chapter covers all live animals except : (a) fish and crustaceans, molluscs and other aquatic invertebrates, of heading 0301, 0306, 0307 or 0308; (b) cultures of micro-organisms and other products of heading 3002; and (c) animals of heading 9508.'),
  ('01', 'cultures of micro-organisms and other products of heading 3002', '30', '3002', 'Note 1', 'This Chapter covers all live animals except : (a) fish and crustaceans, molluscs and other aquatic invertebrates, of heading 0301, 0306, 0307 or 0308; (b) cultures of micro-organisms and other products of heading 3002; and (c) animals of heading 9508.'),
  ('01', 'animals of heading 9508', '95', '9508', 'Note 1', 'This Chapter covers all live animals except : (a) fish and crustaceans, molluscs and other aquatic invertebrates, of heading 0301, 0306, 0307 or 0308; (b) cultures of micro-organisms and other products of heading 3002; and (c) animals of heading 9508.'),
  ('01', 'Germplasm of cattle', '05', '0511', 'Export Licensing Note 3', 'Germplasm of cattle is classified in heading 0511'),
  ('02', 'products of the kinds described in headings 0201 to 0208 or 0210, unfit or unsuitable for human consumption', NULL, NULL, 'Note 1(a)', 'This Chapter does not cover : (a) products of the kinds described in headings 0201 to 0208 or 0210, unfit or unsuitable for human consumption; (b) edible, non-living insects (heading 0410); (c) guts, bladders or stomachs of animals (heading 0504) or animal blood (heading 0511 or 3002); or (d) animal fat, other than products of heading 0209 (Chapter 15).'),
  ('02', 'edible, non-living insects', '04', '0410', 'Note 1(b)', 'This Chapter does not cover : (a) products of the kinds described in headings 0201 to 0208 or 0210, unfit or unsuitable for human consumption; (b) edible, non-living insects (heading 0410); (c) guts, bladders or stomachs of animals (heading 0504) or animal blood (heading 0511 or 3002); or (d) animal fat, other than products of heading 0209 (Chapter 15).'),
  ('02', 'guts, bladders or stomachs of animals', '05', '0504', 'Note 1(c)', 'This Chapter does not cover : (a) products of the kinds described in headings 0201 to 0208 or 0210, unfit or unsuitable for human consumption; (b) edible, non-living insects (heading 0410); (c) guts, bladders or stomachs of animals (heading 0504) or animal blood (heading 0511 or 3002); or (d) animal fat, other than products of heading 0209 (Chapter 15).'),
  ('02', 'animal blood (heading 0511)', '05', '0511', 'Note 1(c)', 'This Chapter does not cover : (a) products of the kinds described in headings 0201 to 0208 or 0210, unfit or unsuitable for human consumption; (b) edible, non-living insects (heading 0410); (c) guts, bladders or stomachs of animals (heading 0504) or animal blood (heading 0511 or 3002); or (d) animal fat, other than products of heading 0209 (Chapter 15).'),
  ('02', 'animal blood (heading 3002)', '30', '3002', 'Note 1(c)', 'This Chapter does not cover : (a) products of the kinds described in headings 0201 to 0208 or 0210, unfit or unsuitable for human consumption; (b) edible, non-living insects (heading 0410); (c) guts, bladders or stomachs of animals (heading 0504) or animal blood (heading 0511 or 3002); or (d) animal fat, other than products of heading 0209 (Chapter 15).'),
  ('02', 'animal fat, other than products of heading 0209', '15', NULL, 'Note 1(d)', 'This Chapter does not cover : (a) products of the kinds described in headings 0201 to 0208 or 0210, unfit or unsuitable for human consumption; (b) edible, non-living insects (heading 0410); (c) guts, bladders or stomachs of animals (heading 0504) or animal blood (heading 0511 or 3002); or (d) animal fat, other than products of heading 0209 (Chapter 15).'),
  ('03', 'mammals of heading 0106', '01', '0106', 'Note 1(a)', 'This Chapter does not cover : (a) mammals of heading 0106; (b) meat of mammals of heading 0106 ( heading 0208 or 0210); (c) fish (includinglivers,roes andmilt thereof) or crustaceans,molluscs or other aquatic invertebrates, dead and unfit or unsuitable for human consumption by reason of either their species or their condition (Chapter 5); flours, meals or pellets of fish or of crustaceans, molluscs or other aquatic invertebrates, unfit for human consumption (heading 2301); or (d) caviar or caviar substitutes prepared from fish eggs (heading 1604).'),
  ('03', 'meat of mammals of heading 0106', '02', '0208', 'Note 1(b)', 'This Chapter does not cover : (a) mammals of heading 0106; (b) meat of mammals of heading 0106 ( heading 0208 or 0210); (c) fish (includinglivers,roes andmilt thereof) or crustaceans,molluscs or other aquatic invertebrates, dead and unfit or unsuitable for human consumption by reason of either their species or their condition (Chapter 5); flours, meals or pellets of fish or of crustaceans, molluscs or other aquatic invertebrates, unfit for human consumption (heading 2301); or (d) caviar or caviar substitutes prepared from fish eggs (heading 1604).'),
  ('03', 'meat of mammals of heading 0106 (alternative heading)', '02', '0210', 'Note 1(b)', 'This Chapter does not cover : (a) mammals of heading 0106; (b) meat of mammals of heading 0106 ( heading 0208 or 0210); (c) fish (includinglivers,roes andmilt thereof) or crustaceans,molluscs or other aquatic invertebrates, dead and unfit or unsuitable for human consumption by reason of either their species or their condition (Chapter 5); flours, meals or pellets of fish or of crustaceans, molluscs or other aquatic invertebrates, unfit for human consumption (heading 2301); or (d) caviar or caviar substitutes prepared from fish eggs (heading 1604).'),
  ('03', 'fish (including livers, roes and milt thereof) or crustaceans, molluscs or other aquatic invertebrates, dead and unfit or unsuitable for human consumption by reason of either their species or their condition', '05', NULL, 'Note 1(c)', 'This Chapter does not cover : (a) mammals of heading 0106; (b) meat of mammals of heading 0106 ( heading 0208 or 0210); (c) fish (includinglivers,roes andmilt thereof) or crustaceans,molluscs or other aquatic invertebrates, dead and unfit or unsuitable for human consumption by reason of either their species or their condition (Chapter 5); flours, meals or pellets of fish or of crustaceans, molluscs or other aquatic invertebrates, unfit for human consumption (heading 2301); or (d) caviar or caviar substitutes prepared from fish eggs (heading 1604).'),
  ('03', 'flours, meals or pellets of fish or of crustaceans, molluscs or other aquatic invertebrates, unfit for human consumption', '23', '2301', 'Note 1(c)', 'This Chapter does not cover : (a) mammals of heading 0106; (b) meat of mammals of heading 0106 ( heading 0208 or 0210); (c) fish (includinglivers,roes andmilt thereof) or crustaceans,molluscs or other aquatic invertebrates, dead and unfit or unsuitable for human consumption by reason of either their species or their condition (Chapter 5); flours, meals or pellets of fish or of crustaceans, molluscs or other aquatic invertebrates, unfit for human consumption (heading 2301); or (d) caviar or caviar substitutes prepared from fish eggs (heading 1604).'),
  ('03', 'caviar or caviar substitutes prepared from fish eggs', '16', '1604', 'Note 1(d)', 'This Chapter does not cover : (a) mammals of heading 0106; (b) meat of mammals of heading 0106 ( heading 0208 or 0210); (c) fish (includinglivers,roes andmilt thereof) or crustaceans,molluscs or other aquatic invertebrates, dead and unfit or unsuitable for human consumption by reason of either their species or their condition (Chapter 5); flours, meals or pellets of fish or of crustaceans, molluscs or other aquatic invertebrates, unfit for human consumption (heading 2301); or (d) caviar or caviar substitutes prepared from fish eggs (heading 1604).'),
  ('04', 'non-living insects, unfit for human consumption', '05', '0511', 'Note 5(a)', 'This Chapter does not cover: (a) non-living insects, unfit for human consumption (heading 0511); (b) products obtained from whey, containing by weight more than 95% lactose, expressed as anhydrous lactose, calculated on the dry matter (heading 1702); (c) products obtained from milk by replacing one or more of its natural constituents (for example, butyric fats) by another substance (for example, oleic fats) (heading 1901 or 2106); or (d) Albumins (including concentrates of two or more whey proteins, containing by weight more than 80% whey proteins, calculated on the dry matter) (heading 3502) or globulins (heading 3504).'),
  ('04', 'products obtained from whey, containing by weight more than 95% lactose, expressed as anhydrous lactose, calculated on the dry matter', '17', '1702', 'Note 5(b)', 'This Chapter does not cover: (a) non-living insects, unfit for human consumption (heading 0511); (b) products obtained from whey, containing by weight more than 95% lactose, expressed as anhydrous lactose, calculated on the dry matter (heading 1702); (c) products obtained from milk by replacing one or more of its natural constituents (for example, butyric fats) by another substance (for example, oleic fats) (heading 1901 or 2106); or (d) Albumins (including concentrates of two or more whey proteins, containing by weight more than 80% whey proteins, calculated on the dry matter) (heading 3502) or globulins (heading 3504).'),
  ('04', 'products obtained from milk by replacing one or more of its natural constituents (for example, butyric fats) by another substance (for example, oleic fats)', '19', '1901', 'Note 5(c)', 'This Chapter does not cover: (a) non-living insects, unfit for human consumption (heading 0511); (b) products obtained from whey, containing by weight more than 95% lactose, expressed as anhydrous lactose, calculated on the dry matter (heading 1702); (c) products obtained from milk by replacing one or more of its natural constituents (for example, butyric fats) by another substance (for example, oleic fats) (heading 1901 or 2106); or (d) Albumins (including concentrates of two or more whey proteins, containing by weight more than 80% whey proteins, calculated on the dry matter) (heading 3502) or globulins (heading 3504).'),
  ('04', 'products obtained from milk by replacing one or more of its natural constituents (for example, butyric fats) by another substance (for example, oleic fats)', '21', '2106', 'Note 5(c)', 'This Chapter does not cover: (a) non-living insects, unfit for human consumption (heading 0511); (b) products obtained from whey, containing by weight more than 95% lactose, expressed as anhydrous lactose, calculated on the dry matter (heading 1702); (c) products obtained from milk by replacing one or more of its natural constituents (for example, butyric fats) by another substance (for example, oleic fats) (heading 1901 or 2106); or (d) Albumins (including concentrates of two or more whey proteins, containing by weight more than 80% whey proteins, calculated on the dry matter) (heading 3502) or globulins (heading 3504).'),
  ('04', 'Albumins (including concentrates of two or more whey proteins, containing by weight more than 80% whey proteins, calculated on the dry matter)', '35', '3502', 'Note 5(d)', 'This Chapter does not cover: (a) non-living insects, unfit for human consumption (heading 0511); (b) products obtained from whey, containing by weight more than 95% lactose, expressed as anhydrous lactose, calculated on the dry matter (heading 1702); (c) products obtained from milk by replacing one or more of its natural constituents (for example, butyric fats) by another substance (for example, oleic fats) (heading 1901 or 2106); or (d) Albumins (including concentrates of two or more whey proteins, containing by weight more than 80% whey proteins, calculated on the dry matter) (heading 3502) or globulins (heading 3504).'),
  ('04', 'globulins', '35', '3504', 'Note 5(d)', 'This Chapter does not cover: (a) non-living insects, unfit for human consumption (heading 0511); (b) products obtained from whey, containing by weight more than 95% lactose, expressed as anhydrous lactose, calculated on the dry matter (heading 1702); (c) products obtained from milk by replacing one or more of its natural constituents (for example, butyric fats) by another substance (for example, oleic fats) (heading 1901 or 2106); or (d) Albumins (including concentrates of two or more whey proteins, containing by weight more than 80% whey proteins, calculated on the dry matter) (heading 3502) or globulins (heading 3504).'),
  ('04', 'edible non-living insects otherwise prepared or preserved', NULL, NULL, 'Note 6', 'For the purposes of heading 0410, the term "insects" means edible non-living insects, whole or in parts, fresh, chilled, frozen, dried, smoked, salted or in brine, as well as flours and meals of insects, fit for human consumption. However, it does not cover edible non-living insects otherwise prepared or preserved (generally Section IV).'),
  ('04', 'dehydrated butter or ghee', '04', '0405', 'Sub-Heading Note 2', 'For the purposes of sub-heading 0405 10, the term "butter" does not include dehydrated butter or ghee (sub-heading 0405 90).'),
  ('05', 'edible products (other than guts, bladders and stomachs of animals, whole and pieces thereof, and animal blood, liquid or dried)', NULL, NULL, 'Note 1(a)', 'This Chapter does not cover: (a) edible products(other than guts, bladders and stomachs of animals, whole and piecesthereof, and animal blood, liquid or dried)'),
  ('05', 'hides or skins (including furskins) other than goods of heading 0505 and parings and similar waste of raw hides or skins of heading 0511', '41', NULL, 'Note 1(b)', '(b) hides or skins (including furskins) other than goods of heading 0505 and parings and similar waste of raw hides or skins of heading 0511 (Chapter 41 or 43)'),
  ('05', 'hides or skins (including furskins) other than goods of heading 0505 and parings and similar waste of raw hides or skins of heading 0511', '43', NULL, 'Note 1(b)', '(b) hides or skins (including furskins) other than goods of heading 0505 and parings and similar waste of raw hides or skins of heading 0511 (Chapter 41 or 43)'),
  ('05', 'animal textile materials, other than horsehair and horsehair waste', NULL, NULL, 'Note 1(c)', '(c) animal textile materials, other than horsehair and horsehair waste (Section XI)'),
  ('05', 'prepared knots or tufts for broom or brush making', '96', '9603', 'Note 1(d)', '(d) prepared knots or tufts for broom or brush making (heading 9603)'),
  ('06', 'potatoes', '07', NULL, 'Note 1', 'Subject to the second part of heading 0601, this Chapter covers only live trees and goods (including seedling vegetables) of a kind commonly supplied by nursery gardeners or florists for planting or for ornamental use; nevertheless it does not include potatoes, onions,shallots, garlic or other products of Chapter 7.'),
  ('06', 'onions', '07', NULL, 'Note 1', 'Subject to the second part of heading 0601, this Chapter covers only live trees and goods (including seedling vegetables) of a kind commonly supplied by nursery gardeners or florists for planting or for ornamental use; nevertheless it does not include potatoes, onions,shallots, garlic or other products of Chapter 7.'),
  ('06', 'shallots', '07', NULL, 'Note 1', 'Subject to the second part of heading 0601, this Chapter covers only live trees and goods (including seedling vegetables) of a kind commonly supplied by nursery gardeners or florists for planting or for ornamental use; nevertheless it does not include potatoes, onions,shallots, garlic or other products of Chapter 7.'),
  ('06', 'garlic', '07', NULL, 'Note 1', 'Subject to the second part of heading 0601, this Chapter covers only live trees and goods (including seedling vegetables) of a kind commonly supplied by nursery gardeners or florists for planting or for ornamental use; nevertheless it does not include potatoes, onions,shallots, garlic or other products of Chapter 7.'),
  ('06', 'other products of Chapter 7', '07', NULL, 'Note 1', 'Subject to the second part of heading 0601, this Chapter covers only live trees and goods (including seedling vegetables) of a kind commonly supplied by nursery gardeners or florists for planting or for ornamental use; nevertheless it does not include potatoes, onions,shallots, garlic or other products of Chapter 7.'),
  ('06', 'collages or similar decorative plaques', '97', '9701', 'Note 2', 'Any reference in heading 0603 or 0604 to goods of any kind shall be construed as including a reference to bouquets, floral baskets, wreaths and similar articles made wholly or partly of goods of that kind, account not being taken of accessories of other materials. However, these headings do not include collages or similar decorative plaques of heading 9701.'),
  ('07', 'forage products', '12', '1214', 'Note 1', 'This Chapter does not cover forage products of heading 1214.'),
  ('07', 'dried leguminous vegetables, shelled', '07', '0713', 'Note 3(a)', 'Heading 0712 covers all dried vegetables of the kinds falling in headings 0701 to 0711, other than: (a) dried leguminous vegetables,shelled (heading 0713); (b) sweet corn in the forms specified in headings 1102 to 1104; (c) flour, meal, powder, flakes, granules and pellets of potatoes (heading 1105); (d) flour, meal and powder of the dried leguminous vegetables of heading 0713 (heading 1106).'),
  ('07', 'sweet corn in the forms specified in headings 1102 to 1104', '11', '1102', 'Note 3(b)', 'Heading 0712 covers all dried vegetables of the kinds falling in headings 0701 to 0711, other than: (a) dried leguminous vegetables,shelled (heading 0713); (b) sweet corn in the forms specified in headings 1102 to 1104; (c) flour, meal, powder, flakes, granules and pellets of potatoes (heading 1105); (d) flour, meal and powder of the dried leguminous vegetables of heading 0713 (heading 1106).'),
  ('07', 'flour, meal, powder, flakes, granules and pellets of potatoes', '11', '1105', 'Note 3(c)', 'Heading 0712 covers all dried vegetables of the kinds falling in headings 0701 to 0711, other than: (a) dried leguminous vegetables,shelled (heading 0713); (b) sweet corn in the forms specified in headings 1102 to 1104; (c) flour, meal, powder, flakes, granules and pellets of potatoes (heading 1105); (d) flour, meal and powder of the dried leguminous vegetables of heading 0713 (heading 1106).'),
  ('07', 'flour, meal and powder of the dried leguminous vegetables of heading 0713', '11', '1106', 'Note 3(d)', 'Heading 0712 covers all dried vegetables of the kinds falling in headings 0701 to 0711, other than: (a) dried leguminous vegetables,shelled (heading 0713); (b) sweet corn in the forms specified in headings 1102 to 1104; (c) flour, meal, powder, flakes, granules and pellets of potatoes (heading 1105); (d) flour, meal and powder of the dried leguminous vegetables of heading 0713 (heading 1106).'),
  ('07', 'dried or crushed or ground fruits of the genus Capsicum or of the genus Pimenta', '09', '0904', 'Note 4', 'However, dried or crushed or ground fruits of the genus Capsicum or of the genus Pimenta are excluded from this Chapter (heading 0904).'),
  ('08', 'inedible nuts or fruits', NULL, NULL, 'Note 1', 'This Chapter does not cover inedible nuts or fruits.'),
  ('09', 'Cubeb pepper (Piper cubeba)', '12', '1211', 'Note 2', 'This Chapter does not cover Cubeb pepper (Piper cubeba) or other products of heading 1211.'),
  ('09', 'other products of heading 1211', '12', '1211', 'Note 2', 'This Chapter does not cover Cubeb pepper (Piper cubeba) or other products of heading 1211.'),
  ('09', 'mixed condiments or mixed seasonings (where the addition of other substances has caused the mixture to lose the essential character of the goods of headings 0904 to 0910)', '21', '2103', 'Note 1', 'Mixtures of the products of headings 0904 to 0910 are to be classified as follows: (a) mixtures of two or more of the products of the same heading are to be classified in that heading; (b) mixtures of two or more of the products of different headings are to be classified in heading 0910. The addition of other substances to the products of headings 0904 to 0910 [or to the mixtures referred to in paragraph (a) or (b) above] shall not affect their classification provided the resulting mixtures retain the essential character of the goods of those heading. Otherwise such mixtures are not classified in this Chapter; those constituting mixed condiments or mixed seasonings are classified in heading 2103.'),
  ('10', 'grains which have been hulled or otherwise worked', NULL, NULL, '1(b)', 'This Chapter does not cover grains which have been hulled or otherwise worked. However, rice, husked, milled, polished, glazed, parboiled or broken remains classified in heading 1006. Similarly, quinoa from which the pericarp has been wholly or partly removed in order to separate thesaponin, but which has not undergone any other processes, remains classified in heading 1008.'),
  ('10', 'sweet corn', '07', NULL, '2', 'Heading 1005 does not cover sweet corn (Chapter 7).'),
  ('11', 'roasted malt put up as coffee substitutes', '09', '0901', 'Note 1', 'This Chapter does not cover : (a) roasted malt put up as coffee substitutes (heading 0901 or 2101); (b) prepared flours, groats, meals or starches of heading 1901; (c) corn flakes or other products of heading 1904; (d) vegetables, prepared or preserved, of heading 2001, 2004 or 2005; (e) pharmaceutical products (Chapter 30); or (f) starches having the character of perfumery, cosmetic or toilet preparations (Chapter 33).'),
  ('11', 'roasted malt put up as coffee substitutes', '21', '2101', 'Note 1', 'This Chapter does not cover : (a) roasted malt put up as coffee substitutes (heading 0901 or 2101); (b) prepared flours, groats, meals or starches of heading 1901; (c) corn flakes or other products of heading 1904; (d) vegetables, prepared or preserved, of heading 2001, 2004 or 2005; (e) pharmaceutical products (Chapter 30); or (f) starches having the character of perfumery, cosmetic or toilet preparations (Chapter 33).'),
  ('11', 'prepared flours, groats, meals or starches', '19', '1901', 'Note 1', 'This Chapter does not cover : (a) roasted malt put up as coffee substitutes (heading 0901 or 2101); (b) prepared flours, groats, meals or starches of heading 1901; (c) corn flakes or other products of heading 1904; (d) vegetables, prepared or preserved, of heading 2001, 2004 or 2005; (e) pharmaceutical products (Chapter 30); or (f) starches having the character of perfumery, cosmetic or toilet preparations (Chapter 33).'),
  ('11', 'corn flakes or other products of heading 1904', '19', '1904', 'Note 1', 'This Chapter does not cover : (a) roasted malt put up as coffee substitutes (heading 0901 or 2101); (b) prepared flours, groats, meals or starches of heading 1901; (c) corn flakes or other products of heading 1904; (d) vegetables, prepared or preserved, of heading 2001, 2004 or 2005; (e) pharmaceutical products (Chapter 30); or (f) starches having the character of perfumery, cosmetic or toilet preparations (Chapter 33).'),
  ('11', 'vegetables, prepared or preserved', '20', '2001', 'Note 1', 'This Chapter does not cover : (a) roasted malt put up as coffee substitutes (heading 0901 or 2101); (b) prepared flours, groats, meals or starches of heading 1901; (c) corn flakes or other products of heading 1904; (d) vegetables, prepared or preserved, of heading 2001, 2004 or 2005; (e) pharmaceutical products (Chapter 30); or (f) starches having the character of perfumery, cosmetic or toilet preparations (Chapter 33).'),
  ('11', 'vegetables, prepared or preserved', '20', '2004', 'Note 1', 'This Chapter does not cover : (a) roasted malt put up as coffee substitutes (heading 0901 or 2101); (b) prepared flours, groats, meals or starches of heading 1901; (c) corn flakes or other products of heading 1904; (d) vegetables, prepared or preserved, of heading 2001, 2004 or 2005; (e) pharmaceutical products (Chapter 30); or (f) starches having the character of perfumery, cosmetic or toilet preparations (Chapter 33).'),
  ('11', 'vegetables, prepared or preserved', '20', '2005', 'Note 1', 'This Chapter does not cover : (a) roasted malt put up as coffee substitutes (heading 0901 or 2101); (b) prepared flours, groats, meals or starches of heading 1901; (c) corn flakes or other products of heading 1904; (d) vegetables, prepared or preserved, of heading 2001, 2004 or 2005; (e) pharmaceutical products (Chapter 30); or (f) starches having the character of perfumery, cosmetic or toilet preparations (Chapter 33).'),
  ('11', 'pharmaceutical products', '30', NULL, 'Note 1', 'This Chapter does not cover : (a) roasted malt put up as coffee substitutes (heading 0901 or 2101); (b) prepared flours, groats, meals or starches of heading 1901; (c) corn flakes or other products of heading 1904; (d) vegetables, prepared or preserved, of heading 2001, 2004 or 2005; (e) pharmaceutical products (Chapter 30); or (f) starches having the character of perfumery, cosmetic or toilet preparations (Chapter 33).'),
  ('11', 'starches having the character of perfumery, cosmetic or toilet preparations', '33', NULL, 'Note 1', 'This Chapter does not cover : (a) roasted malt put up as coffee substitutes (heading 0901 or 2101); (b) prepared flours, groats, meals or starches of heading 1901; (c) corn flakes or other products of heading 1904; (d) vegetables, prepared or preserved, of heading 2001, 2004 or 2005; (e) pharmaceutical products (Chapter 30); or (f) starches having the character of perfumery, cosmetic or toilet preparations (Chapter 33).'),
  ('11', 'products from the milling of cereals not meeting the starch/ash content thresholds in Note 2(A)', '23', '2302', 'Note 2', '(A) Productsfrom the milling of the cerealslisted in the table below fall in this Chapter if they have, by weight on the dry product : (a) a starch content(determined by themodified Ewers polarimetric method) exceeding that indicated in column (2); and (b) an ash content (after deduction of any added minerals) not exceeding that indicated in column (3). Otherwise, they fall in heading 2302. However, germ of cereals, whole, rolled, flaked or ground, is always classified in heading 1104. (B) Products falling in this Chapter under the above provisions shall be classified in heading 1101 or 1102 if the percentage passing through a woven metal wire cloth sieve with the aperture indicated in column (4) or (5) is not less, by weight, than that shown against the cereal concerned. Otherwise, they fall in heading 1103 or 1104. Cereal Starch content Ash content Rate of passage through a sieve with an aperture of 315 micrometres (microns) 500 micrometres (microns) (1) (2) (3) (4) (5) Wheat and rye 45% 2.5% 80% - Barley 45% 3% 80% - Oats 45% 5% 8 0% - Maize (corn) and 45% 2% - 90% grain soghum Rice 45% 1.6% 80% - Buckwheat 45% 4% 80% -'),
  ('12', 'products of heading 0801', '08', '0801', 'Note 1', 'Heading 1207 applies, inter alia, to palm nuts and kernels, cotton seeds, castor oil seeds, sesamum seeds, mustard seeds, safflower seeds, poppy seeds and shea nuts (karite nuts). It does not apply to products of heading 0801 or 0802 or to olives (Chapter 7 or Chapter 20).'),
  ('12', 'products of heading 0802', '08', '0802', 'Note 1', 'Heading 1207 applies, inter alia, to palm nuts and kernels, cotton seeds, castor oil seeds, sesamum seeds, mustard seeds, safflower seeds, poppy seeds and shea nuts (karite nuts). It does not apply to products of heading 0801 or 0802 or to olives (Chapter 7 or Chapter 20).'),
  ('12', 'olives', '07', NULL, 'Note 1', 'Heading 1207 applies, inter alia, to palm nuts and kernels, cotton seeds, castor oil seeds, sesamum seeds, mustard seeds, safflower seeds, poppy seeds and shea nuts (karite nuts). It does not apply to products of heading 0801 or 0802 or to olives (Chapter 7 or Chapter 20).'),
  ('12', 'olives (preserved or prepared)', '20', NULL, 'Note 1', 'Heading 1207 applies, inter alia, to palm nuts and kernels, cotton seeds, castor oil seeds, sesamum seeds, mustard seeds, safflower seeds, poppy seeds and shea nuts (karite nuts). It does not apply to products of heading 0801 or 0802 or to olives (Chapter 7 or Chapter 20).'),
  ('12', 'residues of headings 2304 to 2306 (oil-cake and other solid residues)', '23', '2304', 'Note 2', 'Heading 1208 applies not only to non-defatted flours and meals but also to flours and meals which have been partially defatted or defatted and wholly or partially refatted with their original oils. It does not, however, apply to residues of headings 2304 to 2306.'),
  ('12', 'leguminous vegetables or sweet corn for sowing', '07', NULL, 'Note 3', 'For the purposes of heading 1209, beet seeds, grass and other herbage seeds, seeds of ornamental flowers, vegetable seeds, seeds of forest trees, seeds of fruit trees, seeds of vetches (other than those of the species Vicia faba) or of lupines are to be regarded as ""seeds of a kind used for sowing"". Heading 1209 does not, however, apply to the following even if for sowing : (a) leguminous vegetables or sweet corn (Chapter 7); (b) spices or other products of Chapter 9; (c) cereals (Chapter 10); or (d) products of headings 1201 to 1207 or 1211.'),
  ('12', 'spices or other products of Chapter 9 (even if for sowing)', '09', NULL, 'Note 3', 'For the purposes of heading 1209, beet seeds, grass and other herbage seeds, seeds of ornamental flowers, vegetable seeds, seeds of forest trees, seeds of fruit trees, seeds of vetches (other than those of the species Vicia faba) or of lupines are to be regarded as ""seeds of a kind used for sowing"". Heading 1209 does not, however, apply to the following even if for sowing : (a) leguminous vegetables or sweet corn (Chapter 7); (b) spices or other products of Chapter 9; (c) cereals (Chapter 10); or (d) products of headings 1201 to 1207 or 1211.'),
  ('12', 'cereals (even if for sowing)', '10', NULL, 'Note 3', 'For the purposes of heading 1209, beet seeds, grass and other herbage seeds, seeds of ornamental flowers, vegetable seeds, seeds of forest trees, seeds of fruit trees, seeds of vetches (other than those of the species Vicia faba) or of lupines are to be regarded as ""seeds of a kind used for sowing"". Heading 1209 does not, however, apply to the following even if for sowing : (a) leguminous vegetables or sweet corn (Chapter 7); (b) spices or other products of Chapter 9; (c) cereals (Chapter 10); or (d) products of headings 1201 to 1207 or 1211.'),
  ('12', 'products of headings 1201 to 1207 (even if for sowing)', '12', '1201', 'Note 3', 'For the purposes of heading 1209, beet seeds, grass and other herbage seeds, seeds of ornamental flowers, vegetable seeds, seeds of forest trees, seeds of fruit trees, seeds of vetches (other than those of the species Vicia faba) or of lupines are to be regarded as ""seeds of a kind used for sowing"". Heading 1209 does not, however, apply to the following even if for sowing : (a) leguminous vegetables or sweet corn (Chapter 7); (b) spices or other products of Chapter 9; (c) cereals (Chapter 10); or (d) products of headings 1201 to 1207 or 1211.'),
  ('12', 'products of heading 1211 (even if for sowing)', '12', '1211', 'Note 3', 'For the purposes of heading 1209, beet seeds, grass and other herbage seeds, seeds of ornamental flowers, vegetable seeds, seeds of forest trees, seeds of fruit trees, seeds of vetches (other than those of the species Vicia faba) or of lupines are to be regarded as ""seeds of a kind used for sowing"". Heading 1209 does not, however, apply to the following even if for sowing : (a) leguminous vegetables or sweet corn (Chapter 7); (b) spices or other products of Chapter 9; (c) cereals (Chapter 10); or (d) products of headings 1201 to 1207 or 1211.'),
  ('12', 'medicaments (plants or parts of plants used as medicaments)', '30', NULL, 'Note 4', 'Heading 1211 applies, inter alia, to the following plants or parts thereof: basil, borage, ginseng, hyssop, liquorice, all species of mint, rosemary, rue, sage and wormwood. Heading 1211 does not, however, apply to : (a) medicaments of Chapter 30; (b) perfumery, cosmetic or toilet preparations of Chapter 33; or (c) insecticides, fungicides, herbicides, disinfectants or similar products of heading 3808.'),
  ('12', 'perfumery, cosmetic or toilet preparations', '33', NULL, 'Note 4', 'Heading 1211 applies, inter alia, to the following plants or parts thereof: basil, borage, ginseng, hyssop, liquorice, all species of mint, rosemary, rue, sage and wormwood. Heading 1211 does not, however, apply to : (a) medicaments of Chapter 30; (b) perfumery, cosmetic or toilet preparations of Chapter 33; or (c) insecticides, fungicides, herbicides, disinfectants or similar products of heading 3808.'),
  ('12', 'insecticides, fungicides, herbicides, disinfectants or similar products', '38', '3808', 'Note 4', 'Heading 1211 applies, inter alia, to the following plants or parts thereof: basil, borage, ginseng, hyssop, liquorice, all species of mint, rosemary, rue, sage and wormwood. Heading 1211 does not, however, apply to : (a) medicaments of Chapter 30; (b) perfumery, cosmetic or toilet preparations of Chapter 33; or (c) insecticides, fungicides, herbicides, disinfectants or similar products of heading 3808.'),
  ('12', 'dead single-cell micro-organisms (not ''seaweeds and other algae'' for purposes of heading 1212)', '21', '2102', 'Note 5', 'For the purposes of heading 1212, the term ""seaweeds and other algae"" does not include : (a) dead single-cell micro-organisms of heading 2102; (b) cultures of micro-organisms of heading 3002; or (c) fertilizers of heading 3101 or 3105.'),
  ('12', 'cultures of micro-organisms', '30', '3002', 'Note 5', 'For the purposes of heading 1212, the term ""seaweeds and other algae"" does not include : (a) dead single-cell micro-organisms of heading 2102; (b) cultures of micro-organisms of heading 3002; or (c) fertilizers of heading 3101 or 3105.'),
  ('12', 'fertilizers (algae-based or otherwise) of heading 3101', '31', '3101', 'Note 5', 'For the purposes of heading 1212, the term ""seaweeds and other algae"" does not include : (a) dead single-cell micro-organisms of heading 2102; (b) cultures of micro-organisms of heading 3002; or (c) fertilizers of heading 3101 or 3105.'),
  ('12', 'fertilizers of heading 3105', '31', '3105', 'Note 5', 'For the purposes of heading 1212, the term ""seaweeds and other algae"" does not include : (a) dead single-cell micro-organisms of heading 2102; (b) cultures of micro-organisms of heading 3002; or (c) fertilizers of heading 3101 or 3105.'),
  ('13', 'liquorice extract containing more than 10% by weight of sucrose or put up as confectionery', '17', '1704', 'Note 1(a)', 'Heading 1302 applies, inter alia, to liquorice extract and extract of pyrethrum, extract of hops, extract of aloes and opium. The heading does not apply to: (a) liquorice extract containing more than 10% by weight of sucrose or put up as confectionery (heading 1704); (b) malt extract (heading 1901); (c) extracts of coffee, tea or mate (heading 2101); (d) vegetable saps or extracts constituting alcoholic beverages (Chapter 22); (e) camphor, glycyrrhizin or other products of heading 2914 or 2938; (f) concentrates of poppy straw containing not less than 50% by weight of alkaloids (heading 2939); (g) medicaments of heading 3003 or 3004 or blood - grouping reagents (heading 3882); (h) tanning or dyeing extracts (heading 3201 or 3203); (i) essential oils, concretes, absolutes,resinoids, extracted oleoresins, aqueous distillates or aqueous solutions of essential oils or preparations based on odoriferous substances of a kind used for the manufacture of beverages (Chapter 33); or (j) natural rubber, balata, gutta-percha, guayule, chicle or similar natural gums (heading 4001).'),
  ('13', 'malt extract', '19', '1901', 'Note 1(b)', 'Heading 1302 applies, inter alia, to liquorice extract and extract of pyrethrum, extract of hops, extract of aloes and opium. The heading does not apply to: (a) liquorice extract containing more than 10% by weight of sucrose or put up as confectionery (heading 1704); (b) malt extract (heading 1901); (c) extracts of coffee, tea or mate (heading 2101); (d) vegetable saps or extracts constituting alcoholic beverages (Chapter 22); (e) camphor, glycyrrhizin or other products of heading 2914 or 2938; (f) concentrates of poppy straw containing not less than 50% by weight of alkaloids (heading 2939); (g) medicaments of heading 3003 or 3004 or blood - grouping reagents (heading 3882); (h) tanning or dyeing extracts (heading 3201 or 3203); (i) essential oils, concretes, absolutes,resinoids, extracted oleoresins, aqueous distillates or aqueous solutions of essential oils or preparations based on odoriferous substances of a kind used for the manufacture of beverages (Chapter 33); or (j) natural rubber, balata, gutta-percha, guayule, chicle or similar natural gums (heading 4001).'),
