  ('21', 'prepared enzymes', '35', '3507', '1(h)', 'This Chapter does not cover: (h) prepared enzymes of heading 3507.'),
  ('21', 'Extracts of the substitutes referred to in Note 1 (b) above (i.e. extracts of roasted coffee substitutes containing coffee) — these are INCLUDED in Chapter 21', '21', '2101', '2', 'Extracts of the substitutes referred to in Note 1 (b) above are to be classified in heading 2101.'),
  ('21', 'vaccines', '30', '3002', 'heading_2102_text', 'Heading 2102: Yeasts (active or inactive); other single-cell micro-organisms, dead (but not including vaccines of heading 30.02); prepared baking powders.'),
  ('22', 'products of this Chapter (other than those of heading 2209) prepared for culinary purposes and thereby rendered unsuitable for consumption as beverages', '21', '2103', 'Note 1(a)', 'This Chapter does not cover: (a) products of this Chapter (other than those of heading 2209) prepared for culinary purposes and thereby rendered unsuitable for consumption as beverages (generally heading 2103); (b) sea water (heading 2501); (c) distilled or conductivity water or water of similar purity (heading 2853); (d) acetic acid of concentration exceeding 10 % by weight of acetic acid (heading 2915); (e) medicaments of heading 3003 or 3004; or (f) perfumery or toilet preparations (Chapter 33).'),
  ('22', 'sea water', '25', '2501', 'Note 1(b)', 'This Chapter does not cover: (a) products of this Chapter (other than those of heading 2209) prepared for culinary purposes and thereby rendered unsuitable for consumption as beverages (generally heading 2103); (b) sea water (heading 2501); (c) distilled or conductivity water or water of similar purity (heading 2853); (d) acetic acid of concentration exceeding 10 % by weight of acetic acid (heading 2915); (e) medicaments of heading 3003 or 3004; or (f) perfumery or toilet preparations (Chapter 33).'),
  ('22', 'distilled or conductivity water or water of similar purity', '28', '2853', 'Note 1(c)', 'This Chapter does not cover: (a) products of this Chapter (other than those of heading 2209) prepared for culinary purposes and thereby rendered unsuitable for consumption as beverages (generally heading 2103); (b) sea water (heading 2501); (c) distilled or conductivity water or water of similar purity (heading 2853); (d) acetic acid of concentration exceeding 10 % by weight of acetic acid (heading 2915); (e) medicaments of heading 3003 or 3004; or (f) perfumery or toilet preparations (Chapter 33).'),
  ('22', 'acetic acid of concentration exceeding 10 % by weight of acetic acid', '29', '2915', 'Note 1(d)', 'This Chapter does not cover: (a) products of this Chapter (other than those of heading 2209) prepared for culinary purposes and thereby rendered unsuitable for consumption as beverages (generally heading 2103); (b) sea water (heading 2501); (c) distilled or conductivity water or water of similar purity (heading 2853); (d) acetic acid of concentration exceeding 10 % by weight of acetic acid (heading 2915); (e) medicaments of heading 3003 or 3004; or (f) perfumery or toilet preparations (Chapter 33).'),
  ('22', 'medicaments of heading 3003 or 3004', '30', '3003', 'Note 1(e)', 'This Chapter does not cover: (a) products of this Chapter (other than those of heading 2209) prepared for culinary purposes and thereby rendered unsuitable for consumption as beverages (generally heading 2103); (b) sea water (heading 2501); (c) distilled or conductivity water or water of similar purity (heading 2853); (d) acetic acid of concentration exceeding 10 % by weight of acetic acid (heading 2915); (e) medicaments of heading 3003 or 3004; or (f) perfumery or toilet preparations (Chapter 33).'),
  ('22', 'medicaments of heading 3003 or 3004', '30', '3004', 'Note 1(e)', 'This Chapter does not cover: (a) products of this Chapter (other than those of heading 2209) prepared for culinary purposes and thereby rendered unsuitable for consumption as beverages (generally heading 2103); (b) sea water (heading 2501); (c) distilled or conductivity water or water of similar purity (heading 2853); (d) acetic acid of concentration exceeding 10 % by weight of acetic acid (heading 2915); (e) medicaments of heading 3003 or 3004; or (f) perfumery or toilet preparations (Chapter 33).'),
  ('22', 'perfumery or toilet preparations', '33', NULL, 'Note 1(f)', 'This Chapter does not cover: (a) products of this Chapter (other than those of heading 2209) prepared for culinary purposes and thereby rendered unsuitable for consumption as beverages (generally heading 2103); (b) sea water (heading 2501); (c) distilled or conductivity water or water of similar purity (heading 2853); (d) acetic acid of concentration exceeding 10 % by weight of acetic acid (heading 2915); (e) medicaments of heading 3003 or 3004; or (f) perfumery or toilet preparations (Chapter 33).'),
  ('23', 'vegetable waste, vegetable residues and by-products of vegetable or animal material processing (which retain the essential characteristics of the original material)', NULL, NULL, 'Note 1', 'Heading 2309 includes products of a kind used in animal feeding, not elsewhere specified or included, obtained by processing vegetable or animal materials to such an extent that they have lost the essential characteristics of the original material, other than vegetable waste, vegetable residues and by-products of such processing.'),
  ('24', 'medicinal cigarettes', '30', NULL, 'Note 1', 'This Chapter does not cover medicinal cigarettes (Chapter 30).'),
  ('24', 'tobacco-free products intended for smoking in a water pipe', NULL, NULL, 'Sub-Heading Note 1', 'For the purposes of sub-heading 2403 11, the expression "water pipe tobacco" means tobacco intended for smoking in a water pipe and which consists of a mixture of tobacco and glycerol, whether or not contain-ing aromatic oils and extracts, molasses or sugar, and whether or not flavoured with fruit. However, tobacco-free products intended for smoking in a water pipe are excluded from this sub-heading.'),
  ('25', 'sublimed sulphur, precipitated sulphur and colloidal sulphur', '28', '2802', 'Note 2(a)', 'This Chapter does not cover : (a) sublimed sulphur, precipitated sulphur and colloidal sulphur (heading 2802); (b) earth colours containing 70% or more by weight of combined iron evaluated as Fe2O3 (heading 2821); (c) medicaments and other products of Chapter 30; (d) perfumery, cosmetic or toilet preparations (Chapter 33); (e) dolomite ramming mix (heading 3816); (f) setts, curbstones and flagstones (heading 6801); mosaic cubes or the like (heading 6802); roofing, facing or damp course slates (heading 6803); (g) precious or semi-precious stones (heading 7102 or 7103); (h) cultured crystals (other than optical elements) weighing not less than 2.5g each, of sodium chloride or of magnesiumoxide, of heading 3824; optical elements ofsodiumchloride or of magnesium oxide (heading 9001); (ij) billiard chalks (heading 9504); or (k) writing or drawing chalks and tailors? chalks (heading 9609).'),
