  ('34', 'scouring powders and similar preparations (products containing abrasive powders not in the form of bars, cakes or moulded pieces or shapes are classified in heading 3405)', '34', '3405', 'Note 2', 'For the purposes of heading 3401, the expression "soap" applies only to soap soluble in water. Soap and the other products of heading 3401 may contain added substances (for example, disinfectants, abrasive powders, fillers or medicaments). Products containing abrasive powders remain classified in heading 3401 only if in the form of bars, cakes or moulded pieces or shapes. In other forms they are to be classified in heading 3405 as "scouring powders and similar preparations".'),
  ('34', 'products of headings 1516, 3402 or 3823, even if having a waxy character (excluded from heading 3404)', '15', '1516', 'Note 5(i)', 'the heading does not apply to: (i) products of headings 1516, 3402 or 3823, even if having a waxy character'),
  ('34', 'products of headings 1516, 3402 or 3823, even if having a waxy character (excluded from heading 3404)', '34', '3402', 'Note 5(i)', 'the heading does not apply to: (i) products of headings 1516, 3402 or 3823, even if having a waxy character'),
