  ('34', 'unmixed animal waxes or unmixed vegetable waxes, whether or not refined or coloured, of heading 1521 (excluded from heading 3404)', '15', '1521', 'Note 5(ii)', 'the heading does not apply to: (ii) unmixed animal waxes or unmixed vegetable waxes, whether or not refined or coloured, of heading 1521'),
  ('34', 'mineral waxes and similar products of heading 2712 whether or not intermixed or merely coloured (excluded from heading 3404)', '27', '2712', 'Note 5(iii)', 'the heading does not apply to: (iii) mineral waxes and similar products of heading 2712 whether or not intermixed or merely coloured'),
  ('34', 'waxes mixed with, dispersed in or dissolved in a liquid medium (headings 3405, 3809, etc.) (excluded from heading 3404)', '34', '3405', 'Note 5(iv)', 'the heading does not apply to: (iv) waxes mixed with, dispersed in or dissolved in a liquid medium (headings 3405, 3809, etc.)'),
