  ('36', 'Goods answering to a description in heading 2843, 2846 or 2852 — must be classified in those headings and not elsewhere in Section VI', '28', '2843', 'Section VI Note 1(B)', '(B) Subject to paragraph (A) above, goods answering to a description in heading 2843, 2846 or 2852 are to be classified in those headings and in no other heading of this Section.'),
  ('36', 'Goods classifiable in heading 3004, 3005, 3006, 3212, 3303, 3304, 3305, 3306, 3307, 3506, 3707 or 3808 by reason of being put up in measured doses or for retail sale — classified in those headings only', '30', '3004', 'Section VI Note 2', 'Subject to Note 1 above, goods classifiable in heading 3004, 3005, 3006, 3212, 3303, 3304, 3305, 3306, 3307, 3506, 3707 or 3808 by reason of being put up in measured doses or for retail sale are to be classified in those headings and in no other heading of this Schedule.'),
  ('36', 'products described by name or function in any Section VI heading — classified by name/function and not under heading 3827', NULL, NULL, 'Section VI Note 4', 'Where a product answers to a description in one or more of the headings in Section VI by virtue of being described by name or function and also to heading 3827, then it is classifiable in a heading that references the product by name or function and not under heading 3827.'),
  ('36', 'matches that are pyrotechnic articles of heading 3604 (excluded from heading 3605, which covers matches other than pyrotechnic articles of heading 3604)', '36', '3604', 'Heading 3605 text', 'Matches, other than pyrotechnic articles of heading 36.04.'),
  ('36', 'articles of combustible materials NOT meeting Note 2 of Chapter 36 (i.e., not (a) metaldehyde, hexamethylenetetramine and similar solid/semi-solid prepared fuels; (b) liquid or liquefied-gas fuels in cigarette-lighter-refill containers not exceeding 300 cm3; or (c) resin torches, firelighters and the like) are NOT covered by heading 3606', NULL, NULL, 'Note 2', 'The expression ""articles of combustible materials"" in heading 3606 applies only to: (a) metaldehyde, hexamethylenetetramine and similar substances, put up in forms (for example, tablets, sticks or similar forms) for use as fuels; fuels with a basis of alcohol, and similar prepared fuels, in solid or semi-solid form; (b) liquid or liquefied-gas fuels in containers of a kind used for filling or refilling cigarette or similar lighters and of a capacity not exceeding 300 cm3 ; and (c) resin torches, firelighters and the like.'),
  ('37', 'waste or scrap', NULL, NULL, 'Note 1', 'This Chapter does not cover waste or scrap'),
  ('37', 'Goods (other than radioactive ores) answering to a description in heading 2844 or 2845 — must be classified in those headings and not elsewhere in this Schedule', '28', '2844', 'Section VI Note 1(A)', '(A) Goods (other than radioactive ores) answering to a description in heading 2844 or 2845 are to be classified in those headings and in no other heading of this Schedule.'),
  ('37', 'Goods answering to a description in heading 2843, 2846 or 2852 — must be classified in those headings and not elsewhere in Section VI', '28', '2843', 'Section VI Note 1(B)', '(B) Subject to paragraph (A) above, goods answering to a description in heading 2843, 2846 or 2852 are to be classified in those headings and in no other heading of this Section.'),
