  ('39', 'materials regarded as textile materials of Section XI', NULL, NULL, 'Note 1', 'The expression, however, does not apply to materials regarded as textile materials of Section XI.'),
  ('39', 'Plastics, rubber, and articles thereof, printed with motifs, characters or pictorial representations, which are not merely subsidiary to the primary use of the goods (except for the goods of heading 3918 or 3919)', '49', NULL, 'Section VII Note 2', 'Except for the goods of heading 3918 or 3919, plastics, rubber, and articles thereof, printed with motifs, characters or pictorial representations, which are not merely subsidiary to the primary use of the goods, fall in Chapter 49.'),
